document.addEventListener("DOMContentLoaded", () => {
    initDashboardMetrics();
    renderAllTables();
    setupNavigation();
    setupFilters();
    setupModalClose();
});

function setupNavigation() {
    const navButtons = document.querySelectorAll(".nav-btn");
    const tabContents = document.querySelectorAll(".tab-content");
    navButtons.forEach(btn => {
        btn.addEventListener("click", () => {
            const targetId = btn.getAttribute("data-target");
            navButtons.forEach(b => b.classList.remove("active"));
            tabContents.forEach(tc => tc.classList.remove("active"));
            btn.classList.add("active");
            document.getElementById(targetId).classList.add("active");
        });
    });
}

function initDashboardMetrics() {
    document.getElementById("count-high-actors").innerText = ontologyData.actors.filter(a => a.isHighRisk).length;
    document.getElementById("count-critical-cve").innerText = ontologyData.vulnerabilities.filter(v => v.type === "Critical_Vulnerability").length;
    document.getElementById("count-inferred-triples").innerText = "+" + (ontologyData.vulnerabilities.length + ontologyData.actors.length + ontologyData.software.length + ontologyData.malware.length);
}

function renderAllTables() {
    renderActorsTable(ontologyData.actors);
    renderMalwareTable(ontologyData.malware);
    renderSoftwareTable(ontologyData.software);
    renderVulnerabilitiesTable(ontologyData.vulnerabilities);
}

function renderActorsTable(data) {
    const tbody = document.querySelector("#table-actors tbody");
    if(!tbody) return;
    tbody.innerHTML = "";
    data.forEach(actor => {
        const softTexto = actor.softwares.length > 0 ? actor.softwares.join(", ") : "Ninguno";
        const techTexto = actor.techniques.length > 0 ? actor.techniques.map(t => `<div>• ${t}</div>`).join("") : "<div>Ninguna registrada</div>";
        const cvesTexto = actor.cves.length > 0 ? actor.cves.join(", ") : "Ninguno directo (Inferencia Vacía)";
        
        const badgeClasificacion = actor.isHighRisk 
            ? '<span class="badge badge-red">High_Risk_Threat_Actor</span>' 
            : '<span class="badge badge-metal">Threat_Actor (Base)</span>';
            
        const reglaExplicacion = actor.isHighRisk
            ? "[INFERENCIA SWRL ACTIVADA]\n\nClase inferida: High_Risk_Threat_Actor\n\nRegla:\nThreat_Actor(?a) ^ uses_technique(?a, ?t) ^ High_Impact_Technique(?t) -> High_Risk_Threat_Actor(?a)"
            : "[TAXONOMÍA JERÁRQUICA]\n\nClase actual: Threat_Actor (Base)";

        const tr = document.createElement("tr");
        tr.innerHTML = `
            <td><strong>${actor.name}</strong></td>
            <td>
                <div style="margin-bottom:6px;"><small style='color:var(--neon-blue); font-weight:bold;'>🛠️ SW:</small> <span style="color:#a0aec0;">${softTexto}</span></div>
                <div><small style='color:var(--neon-amber); font-weight:bold;'>⚡ Tec:</small> <span style="color:#e2e8f0; font-size:11px;">PLACEHOLDER_TECH</span></div>
            </td>
            <td><span class="text-blue" style="font-family:'Fira Code', monospace;">PLACEHOLDER_CVES</span></td>
            <td>${badgeClasificacion}</td>
            <td><button class="action-btn" onclick="openTraceModal('${actor.id}', \`${reglaExplicacion}\`)">Ver Regla</button></td>
        `;
        let htmlStr = tr.innerHTML.replace("PLACEHOLDER_TECH", techTexto).replace("PLACEHOLDER_CVES", cvesTexto);
        tr.innerHTML = htmlStr;
        tbody.appendChild(tr);
    });
}

function renderMalwareTable(data) {
    const tbody = document.querySelector("#table-malware tbody");
    if(!tbody) return;
    tbody.innerHTML = "";
    data.forEach(m => {
        const tr = document.createElement("tr");
        tr.innerHTML = `
            <td><span class="text-red">☣️ ${m.name}</span></td>
            <td><span class="badge badge-amber">${m.type}</span></td>
            <td><span class="text-yellow" style="font-size:11px;">PLACEHOLDER_M1</span></td>
            <td><span class="text-blue" style="font-family:'Fira Code', monospace;">PLACEHOLDER_M2</span></td>
            <td><button class="action-btn" onclick="openTraceModal('${m.name}', '${m.trace}')">Trazar Grafo</button></td>
        `;
        let htmlStr = tr.innerHTML.replace("PLACEHOLDER_M1", m.techniques).replace("PLACEHOLDER_M2", m.cves);
        tr.innerHTML = htmlStr;
        tbody.appendChild(tr);
    });
}

function renderSoftwareTable(data) {
    const tbody = document.querySelector("#table-software tbody");
    if(!tbody) return;
    tbody.innerHTML = "";
    data.forEach(s => {
        const tr = document.createElement("tr");
        tr.innerHTML = `
            <td><span class="text-blue">🛠️ ${s.name}</span></td>
            <td><span class="text-muted">${s.actor}</span></td>
            <td><small class="text-yellow">PLACEHOLDER_S1</small></td>
            <td><span class="text-red" style="font-family:'Fira Code', monospace;">PLACEHOLDER_S2</span></td>
            <td><button class="action-btn" onclick="openTraceModal('${s.name}', '${s.trace}')">Trazar Grafo</button></td>
        `;
        let htmlStr = tr.innerHTML.replace("PLACEHOLDER_S1", s.techniques).replace("PLACEHOLDER_S2", s.cves);
        tr.innerHTML = htmlStr;
        tbody.appendChild(tr);
    });
}

function renderVulnerabilitiesTable(data) {
    const tbody = document.querySelector("#table-vulnerabilities tbody");
    if(!tbody) return;
    tbody.innerHTML = "";
    data.forEach(v => {
        let badgeClass = "badge-blue";
        if (v.type === "Critical_Vulnerability") badgeClass = "badge-red";
        else if (v.type === "High_Risk_Vulnerability") badgeClass = "badge-amber";

        const badgeMitigacion = v.mitigated 
            ? '<span class="badge badge-green">Mitigated_Vulnerability</span>' 
            : '<span class="badge badge-metal">No Mitigada</span>';

        const tr = document.createElement("tr");
        tr.innerHTML = `
            <td><strong>${v.cve}</strong></td>
            <td style="font-size:12px; color: #8a99ad;">${v.desc}</td>
            <td><span class="badge ${badgeClass}">${v.severity} (${v.type.split('_')[0]})</span></td>
            <td><span class="text-yellow">${v.cwe}</span></td>
            <td>${badgeMitigacion}</td>
        `;
        tbody.appendChild(tr);
    });
}

function setupFilters() {
    const search = document.getElementById("search-actors");
    if(search) {
        search.addEventListener("input", (e) => {
            const val = e.target.value.toLowerCase();
            const filtered = ontologyData.actors.filter(a => a.name.toLowerCase().includes(val));
            renderActorsTable(filtered);
        });
    }

    const selectSev = document.getElementById("filter-cve-severity");
    if(selectSev) {
        selectSev.addEventListener("change", (e) => {
            const val = e.target.value;
            if (val === "ALL") {
                renderVulnerabilitiesTable(ontologyData.vulnerabilities);
            } else {
                const filtered = ontologyData.vulnerabilities.filter(v => v.type === val);
                renderVulnerabilitiesTable(filtered);
            }}
        );
    }
}

function openTraceModal(title, traceMessage) {
    document.getElementById("modal-title").innerText = "[AUDITORÍA SEMÁNTICA]: " + title.toUpperCase();
    document.getElementById("modal-trace").innerText = traceMessage;
    document.getElementById("cyber-modal").classList.add("active");
}

function setupModalClose() {
    const modal = document.getElementById("cyber-modal");
    const btn = document.getElementById("close-modal-btn");
    if(btn) btn.addEventListener("click", () => modal.classList.remove("active"));
    window.addEventListener("click", (e) => { if (e.target === modal) modal.classList.remove("active"); });
}
